<?php
require_once __DIR__.'/phase5_lib.php';require_login();p5_require_ready();$pdo=db();
$projects=allowed_projects('view_report');$allowed=array_map('intval',array_column($projects,'id'));
$filter=(int)($_GET['project_id']??0);if($filter&&!in_array($filter,$allowed,true)){$filter=0;}
$rows=p5_budget_rows();if($filter)$rows=array_values(array_filter($rows,fn($r)=>(int)$r['id']===$filter));
$from=(string)($_GET['from']??date('Y-01-01'));$to=(string)($_GET['to']??date('Y-m-d'));
if(!valid_date($from)||!valid_date($to)||$from>$to||strtotime($to)-strtotime($from)>366*86400) { $from=date('Y-01-01');$to=date('Y-m-d'); }
$ids=$filter?[$filter]:$allowed;
$trend=[];
if($ids){
    $in=implode(',',$ids);
    $q="SELECT m, SUM(expense_amt) expense, SUM(purchase_amt) purchase FROM (
      SELECT DATE_FORMAT(entry_date,'%Y-%m') m,SUM(amount) expense_amt,0 purchase_amt FROM expenses WHERE status='approved' AND project_id IN ($in) AND entry_date BETWEEN ? AND ? GROUP BY DATE_FORMAT(entry_date,'%Y-%m')
      UNION ALL SELECT DATE_FORMAT(purchase_date,'%Y-%m') m,0 expense_amt,SUM(total_amount) purchase_amt FROM supplier_purchases WHERE project_id IN ($in) AND purchase_date BETWEEN ? AND ? GROUP BY DATE_FORMAT(purchase_date,'%Y-%m')
    ) t GROUP BY m ORDER BY m";
    $st=$pdo->prepare($q);$st->execute([$from,$to,$from,$to]);$trend=$st->fetchAll();
}
$monthMap=[];foreach($trend as $tr)$monthMap[$tr['m']]=$tr;
$monthList=[];
$startMonth=new DateTimeImmutable(substr($from,0,7).'-01');$endMonth=new DateTimeImmutable(substr($to,0,7).'-01');
while($startMonth<=$endMonth){$key=$startMonth->format('Y-m');$monthList[]=['label'=>$key,'expense'=>(float)($monthMap[$key]['expense']??0),'purchase'=>(float)($monthMap[$key]['purchase']??0)];$startMonth=$startMonth->modify('+1 month');}
$totBudget=$totExpense=$totPurchase=$totPaid=0.0;
foreach($rows as $r){$totBudget+=(float)$r['budget_amount'];$totExpense+=(float)$r['expense_amount'];$totPurchase+=(float)$r['purchase_amount'];$totPaid+=(float)$r['supplier_paid'];}
if(($_GET['format']??'')==='csv'){
    $lines=[];foreach($rows as $r)$lines[]=[$r['title'],$r['status'],number_format((float)$r['budget_amount'],2,'.',''),number_format((float)$r['expense_amount'],2,'.',''),number_format((float)$r['purchase_amount'],2,'.',''),number_format(p5_amount_spent($r),2,'.',''),number_format((float)$r['budget_amount']-p5_amount_spent($r),2,'.',''),number_format((float)$r['purchase_amount']-(float)$r['supplier_paid'],2,'.','')];
    p5_csv('jv-budget-report-'.date('Ymd').'.csv',['Project','Status','Budget BDT','Approved expenses BDT','Supplier purchases BDT','Tracked spending BDT','Budget remaining BDT','Supplier due BDT'],$lines);
}
$maxTrend=max(1.0,...array_map(fn($m)=>$m['expense']+$m['purchase'],$monthList));
include 'layout_top.php';
?>
<div class="p5-page" data-p5-page="report"><section class="p5-hero"><div class="p5-hero-inner"><span class="p5-eyebrow">FINANCIAL INTELLIGENCE / 04</span><h1>যে রিপোর্ট দেখে <em>সিদ্ধান্ত সহজ হয়।</em></h1><p>প্রকল্পভিত্তিক Budget vs Actual এবং নির্বাচিত সময়ের Expense/Purchase Trend একসঙ্গে দেখুন।</p></div><span class="p5-hero-art" aria-hidden="true">↗</span></section>
<section class="p5-surface p5-report-controls"><div class="p5-section-heading"><div><span class="p5-overline">REPORT FILTERS</span><h2>রিপোর্টের পরিসর নির্ধারণ</h2><p>নিচের তারিখগুলো Monthly Trend-এ প্রযোজ্য; Budget টেবিলটি শুরু থেকে মোট হিসাব দেখায়।</p></div></div><form method="get" class="p5-form p5-form-three"><div class="p5-field"><label for="rProject">প্রকল্প</label><select id="rProject" name="project_id"><option value="0">সব অনুমোদিত প্রকল্প</option><?php foreach($projects as $p): ?><option value="<?= (int)$p['id'] ?>" <?= $filter===(int)$p['id']?'selected':'' ?>><?= e($p['title']) ?></option><?php endforeach; ?></select></div><div class="p5-field"><label for="rFrom">শুরু</label><input id="rFrom" name="from" type="date" value="<?= e($from) ?>" required></div><div class="p5-field"><label for="rTo">শেষ</label><input id="rTo" name="to" type="date" value="<?= e($to) ?>" required></div><div class="p5-form-foot"><div class="p5-action-row"><button class="p5-btn p5-btn-primary" type="submit">রিপোর্ট দেখুন ↗</button><a class="p5-btn p5-btn-outline" href="?<?= e(http_build_query(['project_id'=>$filter,'from'=>$from,'to'=>$to,'format'=>'csv'])) ?>">Excel / CSV</a><button type="button" class="p5-btn p5-btn-outline" onclick="window.print()">Print / Save as PDF</button></div></div></form></section>
<section class="p5-kpis"><article class="p5-kpi"><span class="p5-kpi-label">মোট বাজেট (All-time)</span><strong><?= p5_cash_view($totBudget) ?></strong><small><?= count($rows) ?>টি প্রকল্প</small></article><article class="p5-kpi"><span class="p5-kpi-label">অনুমোদিত ব্যয়</span><strong><?= p5_cash_view($totExpense) ?></strong><small>All-time expense</small></article><article class="p5-kpi"><span class="p5-kpi-label">Supplier Purchase</span><strong><?= p5_cash_view($totPurchase) ?></strong><small>All-time purchase invoice</small></article><article class="p5-kpi"><span class="p5-kpi-label">Budget Remaining</span><strong class="<?= ($totBudget-$totExpense-$totPurchase)<0?'p5-negative':'' ?>"><?= p5_cash_view($totBudget-$totExpense-$totPurchase) ?></strong><small>Approval + Purchase বাদ দিয়ে</small></article></section>
<section class="p5-surface"><div class="p5-section-heading"><div><span class="p5-overline">MONTHLY FLOW</span><h2>খরচের মাসভিত্তিক প্রবণতা</h2><p><?= e($from) ?> — <?= e($to) ?> · অনুমোদিত ব্যয় ও Supplier Purchase (Payment নয়)</p></div></div><div class="p5-legend"><span><i class="legend-exp"></i> Approved Expense</span><span><i class="legend-pur"></i> Supplier Purchase</span></div>
<?php if(array_sum(array_map(fn($m)=>$m['expense']+$m['purchase'],$monthList))>0): ?><div class="p5-chart" aria-label="মাসভিত্তিক খরচের তুলনা"><?php foreach($monthList as $m): $den=max(1,$maxTrend); ?><div class="p5-chart-row"><span><?= e($m['label']) ?></span><div class="p5-chart-track"><i class="p5-chart-exp" style="width:<?= round($m['expense']/$den*100,2) ?>%"></i><i class="p5-chart-pur" style="width:<?= round($m['purchase']/$den*100,2) ?>%"></i></div><strong><?= p5_cash_view($m['expense']+$m['purchase']) ?></strong></div><?php endforeach; ?></div><?php else: ?><div class="p5-empty">এই সময়ে কোনো অনুমোদিত ব্যয় বা Supplier Purchase নেই।</div><?php endif; ?></section>
<section class="p5-surface"><div class="p5-section-heading"><div><span class="p5-overline">BUDGET VS ACTUAL</span><h2>প্রকল্পভিত্তিক আর্থিক প্রতিবেদন</h2><p>Full Project Cost View (ব্যয় + Purchase) এবং Supplier Due</p></div></div><?php if($rows): ?><div class="p5-toolbar"><label class="p5-search"><input data-p5-search type="search" placeholder="প্রকল্প খুঁজুন..."></label></div><div class="p5-table-scroll"><table class="p5-table" data-p5-table><thead><tr><th>প্রকল্প</th><th>বাজেট</th><th>Approved Expense</th><th>Purchase</th><th>Tracked Spend</th><th>Budget Remaining</th><th>Supplier Due</th></tr></thead><tbody><?php foreach($rows as $r): $spend=p5_amount_spent($r); ?><tr data-p5-row><td><strong><?= e($r['title']) ?></strong></td><td><?= p5_cash_view($r['budget_amount']) ?></td><td><?= p5_cash_view($r['expense_amount']) ?></td><td><?= p5_cash_view($r['purchase_amount']) ?></td><td><?= p5_cash_view($spend) ?></td><td class="<?= (float)$r['budget_amount']-$spend<0?'p5-negative':'' ?>"><?= p5_cash_view((float)$r['budget_amount']-$spend) ?></td><td><?= p5_cash_view((float)$r['purchase_amount']-(float)$r['supplier_paid']) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="p5-empty" data-p5-no-match hidden>এমন কোনো প্রকল্প পাওয়া যায়নি।</div><?php else: ?><div class="p5-empty">এই Report-এর জন্য অনুমোদিত Project নেই।</div><?php endif; ?></section>
<p class="p5-note">Budget Report-এ Supplier Purchase পুরো Invoice Value হিসাব করা হয়; পরে Payment করলে খরচ আবার যোগ হয় না। Employee Advance-ও নিজে খরচ নয়। Browser-এর Print অপশন থেকে Save as PDF এবং Excel-এ Import করার জন্য CSV Download ব্যবহার করুন (native .xlsx নয়)।</p></div><script src="assets/phase5.js?v=5.0.0" defer></script>
